class Animal{constructor(e){this.name=e}speak(){return this.name+" makes a sound"}describe(){return"Animal:"+this.name}}class Dog extends Animal{constructor(e,s){super(e),this.breed=s}speak(){return super.speak()+" (specifically, barks)"}describe(){return super.describe()+", breed="+this.breed}}class Puppy extends Dog{speak(){return super.speak()+" [in a tiny voice]"}}const a=new Animal("Generic"),d=new Dog("Rex","Labrador"),pu=new Puppy("Tiny","Poodle");print(a.speak()),print(d.speak()),print(d.describe()),print(pu.speak()),print(pu instanceof Dog,pu instanceof Animal);